from typing import List


def maximize_strength(n: int, m: int, machine_power: List[List[int]]) -> int:
    if n == 1:
        return min(machine_power[0])
    firsts, seconds = [], []
    for row in machine_power:
        a, b = sorted(row)[:2]          # 最小值、次小值（m >= 2）
        firsts.append(a)
        seconds.append(b)
    # 次小值最小的机器当"接收机"，其余机器都把最小单元转给它
    return sum(seconds) - min(seconds) + min(firsts)
